import React from "react";

function ResumePreview({ data }) {
  return (
    <div style={{ width: "30%", background: "#f4f4f4", padding: "10px" }}>
      <h2>Preview</h2>

      <h1>{data.name}</h1>
      <p>{data.email}</p>

      <h3>Summary</h3>
      <p>{data.summary}</p>

      <h3>Skills</h3>
      <p>{data.skills}</p>
    </div>
  );
}

export default ResumePreview;
